urlset:
{%- for path, freq, prio in [
    ("/", "weekly", "1.0"),
    ("/play", "weekly", "0.9"),
    ("/create_bot_page", "monthly", "0.8"),
    ("/explorer", "hourly", "0.8"),
    ("/world_map", "always", "0.7"),
    ("/players", "hourly", "0.7"),
    ("/start_game_page", "monthly", "0.5"),
] %}

		{{ site_url }}{{ path }}
		{{ freq }}
		{{ prio }}

{%- endfor %}
{%- for type_name in objects_summary %}

		{{ site_url }}/explorer/type/{{ type_name | urlencode }}/
		hourly
		0.6

{%- endfor %}
